"""Only changed Windows parent filtering peers; no passed pointer/geometry replay."""
from pathlib import Path
import argparse,base64,hashlib,json,re,uuid
from driver import ps,q
r=Path(__file__).resolve().parents[2];p=argparse.ArgumentParser();p.add_argument('--stage',type=Path,required=True);a=p.parse_args()
assert json.loads((r/'docs/replica/ENVIRONMENT_LEASE.json').read_text())['resources']['windows']['owner']=='preflight'
v=json.loads(a.stage.read_text());assert v['owner']=='preflight'and v['component']=='capabilitytable'and v['selfContained']and re.fullmatch(r'DBMV-Isolated-preflight-capabilitytable-[0-9a-f]{32}',v['guestFolder'])
nonce=uuid.uuid4().hex;out=a.stage.parent/'actual-windows-groups'/nonce;out.mkdir(parents=True)
name='preflight-capabilitytable-group-'+nonce+'-cases.json';payload=json.dumps([{'id':'ko-904','english':False,'width':904},{'id':'en-904','english':True,'width':904}]).encode();(r/'artifacts/replica/windows-download'/name).write_bytes(payload);sha=hashlib.sha256(payload).hexdigest().upper()
base="$base=Join-Path $env:TEMP "+q(v['guestFolder'])+";$app=Join-Path $base 'app';$out=Join-Path $app "+q('groups-'+nonce)+";"
find="function OwnedWindows{@([System.Windows.Automation.AutomationElement]::RootElement.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition)|Where-Object{$_.Current.Name-eq 'Replica CapabilityTable verification'-and (Get-Process -Id $_.Current.ProcessId).Path-eq ($app+'\\ReplicaProbe.exe')})};"
code=base+find+"$ProgressPreference='SilentlyContinue';if(@(OwnedWindows).Count){throw 'Own Table already open'};New-Item -ItemType Directory $out|Out-Null;"
code+="function Save($name,$value){[IO.File]::WriteAllText((Join-Path $out ($name+'.json')),($value|ConvertTo-Json -Depth 30 -Compress),[Text.UTF8Encoding]::new($false))};"
code+="function WalkerTree($e,$walker,$d=0){if($d-gt 7){throw 'Unexpected Table depth'};$b=$e.Current.BoundingRectangle;$child=$walker.GetFirstChild($e);$children=@();$seen=@{};for($i=0;$null-ne $child-and $i-lt 12;$i++){$key=[string]::Join(',', $child.GetRuntimeId());if($seen.ContainsKey($key)){throw 'Repeated Table sibling'};$seen[$key]=$true;$children+=,(WalkerTree $child $walker ($d+1));$child=$walker.GetNextSibling($child)};if($null-ne $child){throw 'Unexpected Table child count'};return @{id=$e.Current.AutomationId;name=$e.Current.Name;type=$e.Current.ControlType.ProgrammaticName;control=$e.Current.IsControlElement;content=$e.Current.IsContentElement;box=@{x=$b.X;y=$b.Y;width=$b.Width;height=$b.Height};children=$children}}\nfunction RawTree($e){WalkerTree $e ([System.Windows.Automation.TreeWalker]::RawViewWalker)}\nfunction ControlTree($e){WalkerTree $e ([System.Windows.Automation.TreeWalker]::ControlViewWalker)}\n"
code+="Invoke-WebRequest -UseBasicParsing "+q('http://10.211.55.2:8768/'+name)+" -OutFile ($app+'\\groups-cases.json');if((Get-FileHash ($app+'\\groups-cases.json') -Algorithm SHA256).Hash-ne "+q(sha)+"){throw 'Cases hash mismatch'};"
code+="$pidOwned=(Start-Process ($app+'\\ReplicaProbe.exe') -ArgumentList @('--capabilitytable-window',($app+'\\groups-cases.json'),$app) -PassThru).Id;$w=$null;try{"
code+="$until=[DateTime]::UtcNow.AddSeconds(8);do{$wins=@(OwnedWindows);if($wins.Count-eq 1){$w=$wins[0];$table=$w.FindFirst([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::AutomationIdProperty,'CapabilityTable-root'));if($null-ne $table){break}};Start-Sleep -Milliseconds 80}while([DateTime]::UtcNow-lt $until);if($null-eq $table-or [Math]::Abs($table.Current.BoundingRectangle.Width-1808)-gt .01){throw 'Fresh Table not ready'};"
code+="Save 'native-raw-ko' (RawTree $table);Save 'native-control-ko' (ControlTree $table);$next=$w.FindFirst([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::AutomationIdProperty,'CapabilityTable-next'));$next.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern).Invoke();$until=[DateTime]::UtcNow.AddSeconds(2);do{$english=$table.FindFirst([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.PropertyCondition]::new([System.Windows.Automation.AutomationElement]::NameProperty,'Category'));if($null-ne $english){break};Start-Sleep -Milliseconds 50}while([DateTime]::UtcNow-lt $until);if($null-eq $english){throw 'English peer not updated'};"
code+="Save 'native-raw-en' (RawTree $table);Save 'native-control-en' (ControlTree $table);Save 'complete' @{scope='changed Group filtering KOEN2 only';pid=$pidOwned};"
code+="}finally{if($null-ne $w){$w.GetCurrentPattern([System.Windows.Automation.WindowPattern]::Pattern).Close()};$until=[DateTime]::UtcNow.AddSeconds(5);do{$owned=@(Get-Process -Id $pidOwned -ErrorAction SilentlyContinue);if(!$owned.Count){break};Start-Sleep -Milliseconds 80}while([DateTime]::UtcNow-lt $until);Save 'cleanup' @{nativeWindow=@(OwnedWindows).Count;nativeProcess=$owned.Count}};[Console]::WriteLine('Native KOEN trees saved and own window closed')"
(out/'command.json').write_text(json.dumps({'stage':str(a.stage),'guestOutput':'groups-'+nonce,'scope':'actual RawView/ControlView KOEN Group filtering only'},indent=2)+'\n')
try:(out/'command-result.txt').write_text(ps(code,timeout=35))
except Exception as e:(out/'transport-error.txt').write_text(str(e));print(out);raise
names=['native-raw-ko.json','native-control-ko.json','native-raw-en.json','native-control-en.json','complete.json','cleanup.json'];read=base+"foreach($name in @("+','.join(q(n)for n in names)+")){[Console]::WriteLine($name);[Console]::WriteLine([Convert]::ToBase64String([IO.File]::ReadAllBytes((Join-Path $out $name))))}"
lines=ps(read,timeout=20,retry_read=True).splitlines();assert len(lines)==len(names)*2
for i,name in enumerate(names):assert lines[i*2]==name;(out/name).write_bytes(base64.b64decode(lines[i*2+1]))
